  @api wv:moveNodes(moves)  @ 178-180
      @contract  node pos / record-buss pos for {[id]={x,y}} via wm:moveNodes; unknown ids skipped  @ 177
  @api wv:moveBus(id, pos, ext)  @ 183-185
      @contract  buss bar move/resize — writes node pos + record pos & axial ext via wm:moveBus  @ 182
  @api wv:insertBus(spec)  @ 188
      @contract  pass-through to wm:insertBus {pos,orient,node,port,dir}; mints + re-points; returns id  @ 187
  @api wv:spliceable(edgeIdx, nodeId)  @ 191
      @contract  pass-through to wm:spliceable — true iff nodeId may splice into audio edge edgeIdx  @ 190
  @api wv:spliceIntoEdge(edgeIdx, nodeId, pos)  @ 194
      @contract  pass-through to wm:spliceIntoEdge; node lands at pos, gain rides the input side  @ 193
  @api wv:addBusNode(x, y, orient)  @ 197
      @contract  pass-through to wm:addBusNode; mints unwired buss at (x,y); orient defaults 'V'  @ 196
  @api wv:rotateBus(id)  @ 200
      @contract  pass-through to wm:rotateBus — flips the buss's V↔H orientation  @ 199
  @api wv:deleteBus(nodeId)  @ 203
      @contract  pass-through to wm:deleteBus — node, incident edges, record, one Undo block  @ 202
  @api wv:setSourceTagPos(w, offset)  @ 206
      @contract  stashes wireView w's source-tag offset {x,y} (consumer-relative) via wm; decoration only  @ 205
  @api wv:addWire(spec)  @ 209-218
      @contract  appends wire; midi: ports nil; audio: ports default to 1; fires wiringChanged via wm:mutate  @ 208
  @api wv:removeWireAt(idx)  @ 221-225
      @contract  removes the edge at g.edges[idx]; no-op if idx is out of range; fires wiringChanged via wm:mutate  @ 220
  @api wv:deleteNode(nodeId)  @ 228-237
      @contract  removes node and incident edges atomically; no-op if id absent; fires wiringChanged  @ 227
  @api wv:rewireEdgeEnd(idx, side, target)  @ 240-252
      @contract  rewrites one end of g.edges[idx] in place; side ∈ {'from','to'}; target = { id, port? }; port ignored for midi edges; single wiringChanged  @ 239
  @api wv:edgeGain(idx)  @ 255-257
      @contract  live pass-through to wm:edgeGain; 1.0 when ops.gain unset or edge non-audio/missing.  @ 254
  @api wv:setEdgeGain(idx, gain)  @ 260-268
      @contract  writes ops.gain on audio edges[idx]; fast path when poke hosts, else wm:mutate  @ 259
  @api wv:pokeEdgeGain(idx, gain)  @ 271
      @contract  live pass-through to wm:pokeEdgeGain. Returns true if the CU exists and was poked; false if caller must materialise via setEdgeGain first.  @ 270
  @api wv:setMuted(nodeId, on)  @ 274
      @contract  output-mute / read mute for an fx node — pass-through to wm (rm pin-stash)  @ 273
  @api wv:muted(nodeId)  @ 275
  @api wv:setBypassed(nodeId, on)  @ 278
      @contract  bypass / read bypass for an fx node — pass-through to wm (REAPER-native enable)  @ 277
  @api wv:bypassed(nodeId)  @ 279
  @api wv:setEdgePrimary(idx, primary)  @ 282-288
      @contract  sets edges[idx].primary via wm:mutate; coerced to true/nil (nil-not-false per DAG).  @ 281
  @api wv:ancestorsOf(sourceId)  @ 293-296
      @contract  backward reachability over user.edges; returns { [id]=true } including sourceId  @ 292
  @api wv:descendantsOf(sourceId)  @ 299-302
      @contract  forward reachability over user.edges; returns { [id]=true } including sourceId  @ 298
  @api wv:wiredPorts(nodeId, dir)  @ 305-315
      @contract  returns { [portIdx]=true } over audio edges on nodeId for dir ('out'|'in'); midi edges ignored  @ 304
  @api wv:masterPos()  @ 318-322
      @contract  logical canvas position of the master node as x, y; 0,0 if master is somehow absent  @ 317
  @api wv:nodeViews()  @ 328-333
      @contract  returns the list of nodeViews for every node in the current user graph; order unspecified (pairs over graph.nodes)  @ 327
  @api wv:busViews()  @ 337-351
      @contract  one busView per buss record; pos/orient from the node when present, else the record  @ 336
  @api wv:wireViews()  @ 363-400
      -- see docs/wiringView.md § wireView fromKind/fromLabel
      @contract  returns the list of wireViews for every edge in the current user graph; order matches graph.edges  @ 362
  -- Logical view-state (nodeId only)
  @api wv:hover()  @ 404
  @api wv:setHover(id)  @ 405
  @api wv:selection()  @ 408
      @contract  returns the live selection set { [id]=true, … }; callers read, never mutate  @ 407
  @api wv:setSelection(idSet)  @ 410-414
      @contract  replaces selection wholesale; pass {} to clear. Defensive shallow-copies the input.  @ 409
  -- Lifecycle: cache pulled on every structural change
  @api wv:rebuild()  @ 421-423
      -- Lazy sibling of tv:rebuild: invalidate, don't re-pull. The next render
      -- read repopulates via ensureView, so a signal without a render compiles nothing.
      @contract  drops the view cache; next read re-pulls from wm. Driven by wiringChanged.  @ 420

